package brain

import (
	"path/filepath"
	"testing"
)

// serverWrapper has the shape of the script brain's writeServerStoreWrapper
// writes (cmd/bd/brain_stores.go in brain).
const serverWrapper = `#!/bin/sh
# Auto-generated by 'brain stores create task'.
export BEADS_DIR="/data/task/.beads"
export BD_NAME="task"
export BEADS_DOLT_SERVER_MODE=1
exec /opt/bd/bd "$@"
`

// envWrapper has the shape of writeStoreWrapper's script.
const envWrapper = `#!/bin/sh
exec env BEADS_DIR="/data/chores/.beads" BD_NAME="chores" bd "$@"
`

func TestRunnerPrefersTheStoreWrapper(t *testing.T) {
	home := isolate(t)
	path := filepath.Join(home, ".local/bin/task")
	writeFile(t, path, serverWrapper, 0o755)

	r := Store{Name: "task", Path: "/data/task/.beads"}.Runner()
	if r.Wrapper != path || len(r.Env) != 0 {
		t.Errorf("Runner = %+v, want the wrapper at %s", r, path)
	}
}

func TestRunnerAcceptsTheEnvPrefixWrapperShape(t *testing.T) {
	home := isolate(t)
	path := filepath.Join(home, ".local/bin/chores")
	writeFile(t, path, envWrapper, 0o755)
	if r := (Store{Name: "chores", Path: "/data/chores/.beads"}).Runner(); r.Wrapper != path {
		t.Errorf("Runner = %+v", r)
	}
}

func TestRunnerIgnoresAProgramThatIsNotThisStoresWrapper(t *testing.T) {
	home := isolate(t)
	// `task` is also the name of a popular task runner; a binary of that name
	// must never be run as if it were the store.
	writeFile(t, filepath.Join(home, ".local/bin/task"), "#!/bin/sh\necho not brain\n", 0o755)
	r := Store{Name: "task", Path: "/data/task/.beads"}.Runner()
	if r.Wrapper != "" {
		t.Fatalf("Runner = %+v; a script that does not pin BD_NAME is not a wrapper", r)
	}
	wantEnv := []string{"BD_NAME=task", "BEADS_DIR=/data/task/.beads"}
	if len(r.Env) != 2 || r.Env[0] != wantEnv[0] || r.Env[1] != wantEnv[1] {
		t.Errorf("Env = %v, want %v", r.Env, wantEnv)
	}
}

func TestRunnerIgnoresAWrapperForAnotherStore(t *testing.T) {
	home := isolate(t)
	writeFile(t, filepath.Join(home, ".local/bin/brain"), serverWrapper, 0o755) // pins BD_NAME="task"
	if r := (Store{Name: "brain", Path: "/data/brain/.beads"}).Runner(); r.Wrapper != "" {
		t.Errorf("Runner = %+v; a wrapper that pins a different store must not be used", r)
	}
}

func TestRunnerIgnoresANonExecutableFile(t *testing.T) {
	home := isolate(t)
	writeFile(t, filepath.Join(home, ".local/bin/task"), serverWrapper, 0o644)
	if r := (Store{Name: "task", Path: "/data/task/.beads"}).Runner(); r.Wrapper != "" {
		t.Errorf("Runner = %+v", r)
	}
}

func TestPinsNameDoesNotMatchAPrefixOfAnotherName(t *testing.T) {
	if pinsName(`export BD_NAME="tasks"`, "task") {
		t.Error(`BD_NAME="tasks" pins tasks, not task`)
	}
	if !pinsName("BD_NAME=task bd list", "task") {
		t.Error("an unquoted pin must match")
	}
}

func TestGetenvAnswersFromTheWrappersExports(t *testing.T) {
	home := isolate(t)
	writeFile(t, filepath.Join(home, ".local/bin/task"), serverWrapper+"export BEADS_DOLT_SERVER_PORT=3312\nexport BEADS_DOLT_SERVER_HOST='10.0.0.7'\n", 0o755)
	t.Setenv("BEADS_DOLT_SERVER_PORT", "9999")
	t.Setenv("ONLY_IN_PROCESS", "yes")

	get := Store{Name: "task", Path: "/data/task/.beads"}.Getenv()
	if got := get("BEADS_DOLT_SERVER_PORT"); got != "3312" {
		t.Errorf("port = %q; the wrapper's pin must win over b9s's own environment", got)
	}
	if got := get("BEADS_DOLT_SERVER_HOST"); got != "10.0.0.7" {
		t.Errorf("host = %q", got)
	}
	if got := get("BEADS_DOLT_SERVER_MODE"); got != "1" {
		t.Errorf("an unquoted pin = %q", got)
	}
	if got := get("ONLY_IN_PROCESS"); got != "yes" {
		t.Errorf("a variable the wrapper does not pin must come from the process, got %q", got)
	}
}

func TestGetenvWithoutAWrapperIsTheProcessEnvironment(t *testing.T) {
	isolate(t)
	t.Setenv("BEADS_DOLT_SERVER_PORT", "4410")
	if got := (Store{Name: "task"}).Getenv()("BEADS_DOLT_SERVER_PORT"); got != "4410" {
		t.Errorf("port = %q", got)
	}
}
